#include <bits/stdc++.h>
using namespace std;

struct Input {
    long long mod;
    int n, m;
    bool read() {
        return !!(cin >> n >> m >> mod);
    }
};

struct Output {
    long long ans;
    void print() {
        cout << ans << "\n";
    }
};

namespace MainSolution {
    struct Solver {
        long long bin_pow(long long base, long long exp) {
            long long res = 1;
            while (exp > 0) {
                if (exp & 1) res = res * base % mod;
                base = base * base % mod;
                exp >>= 1;
            }
            return res;
        }

        long long mod_inverse(long long x) {
            return bin_pow(x, mod - 2);
        }

        long long C[505][505];

        pair<long long, long long> sequence[505];
        pair<long long, long long> dp[505][505];

        void solve() {
            for (int i = 0; i <= n; ++i) {
                for (int j = 0; j <= n; ++j) {
                    if (i == 0 || j == 0) C[i][j] = 1;
                    else C[i][j] = (C[i - 1][j] + C[i][j - 1]) % mod;
                }
            }

            fill_n(sequence, m + 1, make_pair(0, 0));
            sequence[0] = {1, 0};
            for (int i = 1; i <= m; ++i) {
                for (int j = 0; j < i; ++j) {
                    pair<long long, long long> cur;
                    cur.first = sequence[j].first * sequence[i - 1 - j].first % mod;
                    cur.second = (sequence[j].second * sequence[i - 1 - j].first + sequence[j].first * sequence[i - 1 - j].second) % mod;
                    cur.second = (cur.second * (i + 1) + (ss(j) + ss(i - 1 - j)) * cur.first) % mod;
                    cur.first = cur.first * (i + 1) % mod;
                    cur.first = cur.first * C[j][i - 1 - j] % mod;
                    cur.second = cur.second * C[j][i - 1 - j] % mod;
                    sequence[i].first = (sequence[i].first + cur.first) % mod;
                    sequence[i].second = (sequence[i].second + cur.second) % mod;
                }
            }

            memset(dp, 0, sizeof dp);
            dp[0][0] = {1, 0};
            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= m; ++j) {
                    for (int k = 0; k <= min(n - i, m - j); ++k) {
                        pair<long long, long long> cur;
                        cur.first = sequence[k].first * dp[i][j].first % mod;
                        cur.second = (sequence[k].second * dp[i][j].first + sequence[k].first * dp[i][j].second) % mod;
                        cur.first = cur.first * C[j][k] % mod;
                        cur.second = cur.second * C[j][k] % mod;
                        dp[i + k + 1][j + k].first = (dp[i + k + 1][j + k].first + cur.first) % mod;
                        dp[i + k + 1][j + k].second = (dp[i + k + 1][j + k].second + cur.second) % mod;
                    }
                }
            }
            ans = dp[n + 1][m].second;
        }
        void reset_state() {
            *this = Solver();
        }
    };
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    MainSolution::Solver sol;
    if (getenv("SG")) {
        freopen("problem.in", "r", stdin);
        while (sol.read()) {
            sol.solve();
            sol.print();
            sol.reset_state();
        }
    } else {
        sol.read();
        sol.solve();
        sol.print();
    }
    return 0;
}
